def glob_match(pattern, name):
    """
    Implement fnmatch.fnmatchcase semantics from scratch.

    Supports:
    - * : matches any run of characters (including empty)
    - ? : matches exactly one character
    - [abc] : matches any single character in the set
    - [a-z] : matches any single character in the range
    - [!abc] : matches any single character NOT in the set
    - A ] immediately after [ or [! is treated as a literal ]
    - An unterminated [ is treated as a literal [
    - Matching is anchored to the entire string
    """

    def parse_pattern(pattern):
        """
        Parse the pattern into a list of tokens.
        Each token is either:
        - ('star',)
        - ('question',)
        - ('char', c)
        - ('set', chars_set, negated) where chars_set is a set of characters
        """
        tokens = []
        i = 0
        n = len(pattern)

        while i < n:
            c = pattern[i]

            if c == '*':
                tokens.append(('star',))
                i += 1
            elif c == '?':
                tokens.append(('question',))
                i += 1
            elif c == '[':
                # Try to parse a character set
                j = i + 1
                negated = False
                if j < n and pattern[j] == '!':
                    negated = True
                    j += 1

                # Check if ] is immediately after [ or [!
                if j < n and pattern[j] == ']':
                    # ] is a literal, so this is not a valid set start
                    # Treat [ as literal
                    tokens.append(('char', '['))
                    i += 1
                    continue

                # Parse the set contents
                chars = set()
                found_closing = False

                while j < n:
                    if pattern[j] == ']':
                        found_closing = True
                        break

                    # Check for range
                    if (j + 2 < n and pattern[j + 1] == '-' and pattern[j + 2] != ']'):
                        # It's a range
                        start_char = pattern[j]
                        end_char = pattern[j + 2]
                        if ord(start_char) <= ord(end_char):
                            for k in range(ord(start_char), ord(end_char) + 1):
                                chars.add(chr(k))
                        j += 3
                    else:
                        chars.add(pattern[j])
                        j += 1

                if found_closing:
                    # Valid set
                    tokens.append(('set', chars, negated))
                    i = j + 1  # Move past the ]
                else:
                    # Unterminated [, treat as literal
                    tokens.append(('char', '['))
                    i += 1
            else:
                tokens.append(('char', c))
                i += 1

        return tokens

    def match(tokens, t_idx, name, n_idx):
        """
        Recursive matching with memoization.
        tokens: list of parsed tokens
        t_idx: current index in tokens
        name: the string to match
        n_idx: current index in name
        """
        if t_idx == len(tokens):
            return n_idx == len(name)

        token = tokens[t_idx]

        if token[0] == 'star':
            # * matches any run of characters (including empty)
            # Try matching 0, 1, 2, ... characters
            for k in range(n_idx, len(name) + 1):
                if match(tokens, t_idx + 1, name, k):
                    return True
            return False
        elif token[0] == 'question':
            if n_idx < len(name):
                return match(tokens, t_idx + 1, name, n_idx + 1)
            return False
        elif token[0] == 'char':
            if n_idx < len(name) and name[n_idx] == token[1]:
                return match(tokens, t_idx + 1, name, n_idx + 1)
            return False
        elif token[0] == 'set':
            if n_idx < len(name):
                ch = name[n_idx]
                in_set = ch in token[1]
                if token[2]:  # negated
                    if not in_set:
                        return match(tokens, t_idx + 1, name, n_idx + 1)
                else:
                    if in_set:
                        return match(tokens, t_idx + 1, name, n_idx + 1)
            return False

        return False

    tokens = parse_pattern(pattern)

    # Use memoization to avoid exponential time complexity
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def memo_match(t_idx, n_idx):
        if t_idx == len(tokens):
            return n_idx == len(name)

        token = tokens[t_idx]

        if token[0] == 'star':
            for k in range(n_idx, len(name) + 1):
                if memo_match(t_idx + 1, k):
                    return True
            return False
        elif token[0] == 'question':
            if n_idx < len(name):
                return memo_match(t_idx + 1, n_idx + 1)
            return False
        elif token[0] == 'char':
            if n_idx < len(name) and name[n_idx] == token[1]:
                return memo_match(t_idx + 1, n_idx + 1)
            return False
        elif token[0] == 'set':
            if n_idx < len(name):
                ch = name[n_idx]
                in_set = ch in token[1]
                if token[2]:  # negated
